    // Ensure we work with the correct range by determining the min and max
    const start = Math.min(a, b);
    const end = Math.max(a, b);

    // Array to store even digits
    const evenDigits = [];

    // Iterate through the range from start to end (inclusive)
    for (let num = start; num <= end; num++) {
        // Check if the current number contains any even digit (0,2,4,6,8)
        const digit = num.toString().split('').map(Number);
        const hasEvenDigit = digit.some(digit => digit % 2 === 0);

        // If the number contains any even digit, add it to our result
        if (hasEvenDigit) {
            evenDigits.push(num);
        }
    }

    // Return the result array
    return evenDigits;
}
